// Teensy Soundfont 2 reader - control panel (the same protocol as the C# test GUI)
// connect the serial port first (OSC menu - Connect), then press this button (the other buttons press it if needed)
RED.serial.useTextMode(); // the Teensy answers with text lines
var sf2 = window.sf2 = {};
sf2.node = function (name) { return RED.nodes.namedNode(name); };
sf2.log = function (text) {
    var n = sf2.node("sf2_log");
    n.comment = (n.comment ? n.comment + "\n" : "") + text;
    n.dirty = true;
    RED.view.redraw();
};
sf2.clearLog = function () { var n = sf2.node("sf2_log"); n.comment = ""; n.dirty = true; RED.view.redraw(); };
sf2.cmd = function (text) { RED.serial.sendLine(text); };
sf2.files = []; // {name, size}, size -1 is a directory
sf2.selectedFile = function () {
    var f = sf2.files[sf2.node("sf2_files").selectedIndex];
    if (f == undefined) sf2.log("error: file not selected");
    return f;
};
sf2.selectedInstrument = function () {
    var lb = sf2.node("sf2_instruments");
    if (lb.items == "" || lb.selectedIndex < 0) { sf2.log("error: instrument not selected"); return undefined; }
    return lb.selectedIndex;
};
sf2.progress = function (percent) { var s = sf2.node("sf2_progress"); s.val = percent; s.dirty = true; RED.view.redraw(); };
sf2.parse = function (json) { // the C# GUI used a relaxed JSON parser (single quotes, unquoted names)
    try { return JSON.parse(json); }
    catch (e) { return (new Function("return (" + json + ");"))(); }
};
sf2.decodeJson = function (json) {
    var data;
    try { data = sf2.parse(json); }
    catch (e) { sf2.log("could not parse json: " + json); return; }
    if (data.log != undefined) sf2.log(data.log);
    else if (data.files != undefined) {
        sf2.files = data.files;
        RED.view.ui.setListBoxItems(sf2.node("sf2_files"), data.files.map(function (f) {
            return f.name + "   " + ((f.size != -1) ? f.size : "directory");
        }));
    }
    else if (data.instruments != undefined) {
        RED.view.ui.setListBoxItems(sf2.node("sf2_instruments"), data.instruments.map(function (i) { return i.name + " : " + i.ndx; }));
    }
    else if (data.presets != undefined) {
        RED.view.ui.setListBoxItems(sf2.node("sf2_instruments"), data.presets.map(function (p) {
            return p.name + " : " + p.bank + " : " + p.preset + " : " + p.bagNdx;
        }));
    }
    else if (data.cmd != undefined) {
        if (data.cmd == "file_loaded") sf2.cmd("list_instruments");
        else if (data.cmd == "instrument_loaded") sf2.log("instrument loaded OK");
        else if (data.cmd == "start_send_file_ack") {
            if (sf2.fileToSend == undefined) { sf2.log("error: no file to send"); return; }
            sf2.log("start to send file data");
            RED.serial.sendFile(sf2.fileToSend, function (sent, total) { sf2.progress(Math.round(sent / total * 100)); });
        }
        else if (data.cmd == "fileRxOK") { sf2.log("file rx OK"); sf2.cmd("list_files:"); }
        else if (data.cmd == "deleted_file") { sf2.log("file delete OK"); sf2.cmd("list_files:"); }
        else sf2.log("unknown json cmd: " + data.cmd);
    }
    else sf2.log("rx unknown json: " + json);
};
RED.serial.onLine("sf2", function (line) {
    if (line.startsWith("json:")) sf2.decodeJson(line.substring("json:".length));
    else if (line.length != 0) sf2.log(line);
});
sf2.log("ready");

